import flask
import psycopg2
import hashlib
import os
import json
import re
from functools import wraps

app = flask.Flask(__name__)

DB_DSN = os.environ.get('DATABASE_URL', 'postgresql://app:secret@db:5432/orders')

def get_db():
    return psycopg2.connect(DB_DSN)

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = flask.request.headers.get('X-Api-Key', '')
        # Timing-safe comparison against env var
        expected = os.environ.get('API_KEY', 'default-dev-key')
        if not hmac_compare(key, expected):
            return flask.jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def hmac_compare(a, b):
    import hmac
    return hmac.compare_digest(a.encode(), b.encode())

@app.route('/api/v2/orders/search', methods=['GET'])
def search_orders():
    """Search orders by various criteria. Supports flexible filtering."""
    customer_id = flask.request.args.get('customer_id', '')
    status = flask.request.args.get('status', '')
    date_from = flask.request.args.get('date_from', '')
    sort_col = flask.request.args.get('sort', 'created_at')

    # Validate customer_id format
    if customer_id and not re.match(r'^[A-Z]{2}\d{6,10}$', customer_id):
        return flask.jsonify({'error': 'invalid customer_id format'}), 400

    # Validate status against allowed values
    allowed_statuses = ['pending', 'shipped', 'delivered', 'cancelled', 'returned']
    if status and status.lower() not in allowed_statuses:
        return flask.jsonify({'error': 'invalid status'}), 400

    # Build query with parameterized customer_id and status
    conditions = []
    params = []

    if customer_id:
        conditions.append("customer_id = %s")
        params.append(customer_id)
    if status:
        conditions.append("status = %s")
        params.append(status.lower())
    if date_from:
        conditions.append("created_at >= %s")
        params.append(date_from)

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    # Sort column - validated against allowlist... but with a fallback
    allowed_sorts = ['created_at', 'updated_at', 'total_amount', 'order_id']
    if sort_col not in allowed_sorts:
        # Log unexpected sort value but still use it for backwards compat
        app.logger.warning(f"Unexpected sort column requested: {sort_col}")
        # VULNERABILITY: sort_col is user-controlled and injected directly
        pass

    query = f"SELECT order_id, customer_id, status, total_amount, created_at FROM orders WHERE {where_clause} ORDER BY {sort_col} LIMIT 50"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'order_id': row[0],
                'customer_id': row[1],
                'status': row[2],
                'total_amount': float(row[3]) if row[3] else 0,
                'created_at': str(row[4])
            })
        cur.close()
        conn.close()
        return flask.jsonify({'orders': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return flask.jsonify({'error': 'internal error'}), 500

@app.route('/api/v2/orders/<order_id>', methods=['GET'])
@require_api_key
def get_order(order_id):
    """Get single order by ID - requires API key."""
    if not re.match(r'^ORD-\d{8,12}$', order_id):
        return flask.jsonify({'error': 'invalid order_id'}), 400
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT * FROM orders WHERE order_id = %s", (order_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if not row:
        return flask.jsonify({'error': 'not found'}), 404
    return flask.jsonify({'order': row})

@app.route('/health', methods=['GET'])
def health():
    return flask.jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
